-- Executable DESIGN fixture for the future bridge's app-private configuration DB.
-- No tokens, devices, service, installed settings or real client records are created.
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE clients(client_id TEXT NOT NULL PRIMARY KEY,display_name TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','disabled','revoked')),credential_epoch INTEGER NOT NULL CHECK(credential_epoch>=0),row_version INTEGER NOT NULL CHECK(row_version>=1),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,last_seen_at INTEGER);
CREATE TABLE credentials(credential_id TEXT NOT NULL PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients ON DELETE RESTRICT,verifier BLOB NOT NULL UNIQUE CHECK(length(verifier)=32),key_alias TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','revoked')),created_at INTEGER NOT NULL,expires_at INTEGER,revoked_at INTEGER,epoch INTEGER NOT NULL CHECK(epoch>=0));
CREATE TABLE binding_definitions(binding_id TEXT NOT NULL PRIMARY KEY CHECK(length(binding_id)=64),canonical_signature TEXT NOT NULL UNIQUE,entry_schema_version TEXT NOT NULL);
CREATE TABLE binding_type_schemas(type_schema_id TEXT NOT NULL PRIMARY KEY,schema_hash TEXT NOT NULL UNIQUE CHECK(length(schema_hash)=64),format_version TEXT NOT NULL,canonical_schema_json TEXT NOT NULL CHECK(json_valid(canonical_schema_json)),validation_state TEXT NOT NULL CHECK(validation_state IN ('known','unknown','unsupported')),reason_code TEXT);
CREATE TABLE binding_mappings(binding_id TEXT NOT NULL REFERENCES binding_definitions,schema_hash TEXT NOT NULL CHECK(length(schema_hash)=64),registry_revision INTEGER NOT NULL CHECK(registry_revision>=1),mapping_state TEXT NOT NULL CHECK(mapping_state IN ('known','unknown','unsupported','unreachable')),reason_code TEXT,dispatch_kind TEXT NOT NULL,descriptor TEXT,transaction_code INTEGER,argument_schema_json TEXT NOT NULL CHECK(json_valid(argument_schema_json)),permission_ast_json TEXT NOT NULL CHECK(json_valid(permission_ast_json)),PRIMARY KEY(binding_id,schema_hash));
CREATE TABLE binding_occurrences(binding_id TEXT NOT NULL REFERENCES binding_definitions,source_id TEXT NOT NULL,locator TEXT NOT NULL,record_hash TEXT NOT NULL CHECK(length(record_hash)=64),provenance_json TEXT NOT NULL CHECK(json_valid(provenance_json)),PRIMARY KEY(binding_id,source_id,locator));
CREATE TABLE tools(tool_id TEXT NOT NULL PRIMARY KEY,schema_version TEXT NOT NULL,adapter_version TEXT NOT NULL,capability_key TEXT NOT NULL,scope_schema_version TEXT NOT NULL,risk_class TEXT NOT NULL,registry_revision INTEGER NOT NULL CHECK(registry_revision>=1),executor_kind TEXT NOT NULL DEFAULT 'native' CHECK(executor_kind IN ('native','adb','avalonia')));
CREATE TABLE tool_binding_aliases(tool_id TEXT NOT NULL REFERENCES tools,binding_id TEXT NOT NULL,schema_hash TEXT NOT NULL,canonicalization_version INTEGER NOT NULL CHECK(canonicalization_version>=1),argument_mapping_hash TEXT NOT NULL CHECK(length(argument_mapping_hash)=64),PRIMARY KEY(tool_id,binding_id),FOREIGN KEY(binding_id,schema_hash) REFERENCES binding_mappings);
CREATE TABLE client_binding_rules(client_id TEXT NOT NULL REFERENCES clients ON DELETE CASCADE,binding_id TEXT NOT NULL,schema_hash TEXT NOT NULL,effect TEXT NOT NULL CHECK(effect IN ('deny','ask','allow')),constraints_json TEXT NOT NULL CHECK(json_valid(constraints_json)),row_version INTEGER NOT NULL CHECK(row_version>=1),PRIMARY KEY(client_id,binding_id),FOREIGN KEY(binding_id,schema_hash) REFERENCES binding_mappings);
CREATE TABLE client_tool_rules(client_id TEXT NOT NULL REFERENCES clients ON DELETE CASCADE,tool_id TEXT NOT NULL REFERENCES tools,tool_schema_version TEXT NOT NULL,effect TEXT NOT NULL CHECK(effect IN ('deny','ask','allow')),scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),scope_schema_version TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(client_id,tool_id));
CREATE TABLE tool_guardrails(tool_id TEXT NOT NULL PRIMARY KEY REFERENCES tools,disabled INTEGER NOT NULL CHECK(disabled IN (0,1)),require_ask INTEGER NOT NULL CHECK(require_ask IN (0,1)),scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),scope_schema_version TEXT NOT NULL);
CREATE TABLE policy_state(singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),policy_revision INTEGER NOT NULL CHECK(policy_revision>=1),registry_revision INTEGER NOT NULL CHECK(registry_revision>=1),emergency_deny INTEGER NOT NULL CHECK(emergency_deny IN (0,1)),updated_at INTEGER NOT NULL);
CREATE TABLE executions(execution_id TEXT NOT NULL PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients,credential_id TEXT NOT NULL REFERENCES credentials,tool_id TEXT NOT NULL REFERENCES tools,request_digest BLOB NOT NULL CHECK(length(request_digest)=32),boot_id TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>=1),state TEXT NOT NULL CHECK(state IN ('admitted','dispatched','completed','failed','canceled','unknown')),admitted_at INTEGER NOT NULL,completed_at INTEGER,idempotency_key TEXT,connection_profile_id TEXT REFERENCES connection_profiles,target_id TEXT REFERENCES target_app_profiles,backend_kind TEXT,dispatch_time INTEGER);
CREATE TABLE audit_events(event_id TEXT NOT NULL PRIMARY KEY,occurred_at INTEGER NOT NULL,client_id TEXT REFERENCES clients,tool_id TEXT REFERENCES tools,operation TEXT NOT NULL,decision TEXT NOT NULL,reason_code TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>=1),execution_id TEXT REFERENCES executions,duration_ms INTEGER CHECK(duration_ms>=0));
CREATE TABLE change_outbox(change_id TEXT NOT NULL PRIMARY KEY,policy_revision INTEGER NOT NULL CHECK(policy_revision>=1),change_kind TEXT NOT NULL,affected_client_id TEXT REFERENCES clients,created_at INTEGER NOT NULL,delivered_at INTEGER);
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY CHECK(version>=1),checksum TEXT NOT NULL CHECK(length(checksum)=64),applied_at INTEGER NOT NULL);
CREATE TABLE connection_profiles(profile_id TEXT NOT NULL PRIMARY KEY,backend_kind TEXT NOT NULL CHECK(backend_kind IN ('self_adb','external_adb','avalonia_runtime')),display_name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),row_version INTEGER NOT NULL CHECK(row_version>=1),device_serial_or_binding TEXT,android_user_id INTEGER NOT NULL CHECK(android_user_id>=0),endpoint_metadata_json TEXT NOT NULL CHECK(json_valid(endpoint_metadata_json)),peer_fingerprint TEXT,verification_strength TEXT NOT NULL,secret_ciphertext BLOB,wrapping_key_alias TEXT,paired_at INTEGER,revoked_at INTEGER,CHECK((secret_ciphertext IS NULL)=(wrapping_key_alias IS NULL)));
CREATE TABLE target_app_profiles(target_id TEXT NOT NULL PRIMARY KEY,connection_profile_id TEXT NOT NULL REFERENCES connection_profiles ON DELETE RESTRICT,package_name TEXT NOT NULL,signing_identity TEXT,identity_verification_method TEXT NOT NULL,runtime_protocol TEXT,runtime_endpoint TEXT,server_identity TEXT,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),row_version INTEGER NOT NULL CHECK(row_version>=1));
CREATE TABLE client_raw_grants(client_id TEXT NOT NULL REFERENCES clients ON DELETE CASCADE,connection_id TEXT NOT NULL REFERENCES connection_profiles,descriptor TEXT NOT NULL,code_min INTEGER NOT NULL CHECK(code_min>=0),code_max INTEGER NOT NULL CHECK(code_max>=code_min),flags_mask INTEGER NOT NULL CHECK(flags_mask>=0),contract_hash TEXT NOT NULL CHECK(length(contract_hash)=64),effect TEXT NOT NULL CHECK(effect IN ('deny','ask','allow')),constraints_json TEXT NOT NULL CHECK(json_valid(constraints_json)),row_version INTEGER NOT NULL CHECK(row_version>=1),PRIMARY KEY(client_id,connection_id,descriptor));
CREATE TABLE binding_availability(binding_id TEXT NOT NULL REFERENCES binding_definitions,target_key TEXT NOT NULL REFERENCES target_app_profiles(target_id),state TEXT NOT NULL CHECK(state IN ('available','unavailable','unknown')),reason_code TEXT NOT NULL,os_build TEXT NOT NULL,checked_at INTEGER NOT NULL,PRIMARY KEY(binding_id,target_key));
CREATE TABLE resource_grants(handle_id TEXT NOT NULL PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients ON DELETE CASCADE,exact_uri_ciphertext BLOB NOT NULL,key_alias TEXT NOT NULL,modes TEXT NOT NULL CHECK(modes IN ('read','write','read_write')),enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),revision INTEGER NOT NULL CHECK(revision>=1),created_at INTEGER NOT NULL);
CREATE TABLE bridge_config(singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),row_version INTEGER NOT NULL CHECK(row_version>=1),desired_state TEXT NOT NULL CHECK(desired_state IN ('running','stopped')),start_on_boot INTEGER NOT NULL DEFAULT 0 CHECK(start_on_boot IN (0,1)),last_stop_reason TEXT,fgs_type TEXT NOT NULL,transport_profile TEXT NOT NULL CHECK(transport_profile IN ('paired_tls','reduced_http')),loopback_address TEXT NOT NULL,port_preference INTEGER NOT NULL CHECK(port_preference BETWEEN 0 AND 65535),server_identity_key_alias TEXT NOT NULL,retention_days INTEGER NOT NULL CHECK(retention_days>=0),audit_size_cap INTEGER NOT NULL CHECK(audit_size_cap>0));
CREATE TABLE client_logging_config(client_id TEXT NOT NULL PRIMARY KEY REFERENCES clients ON DELETE CASCADE,mode TEXT NOT NULL CHECK(mode IN ('off','metadata','diagnostic')),paused INTEGER NOT NULL CHECK(paused IN (0,1)),logging_revision INTEGER NOT NULL CHECK(logging_revision>=1),retention_seconds INTEGER NOT NULL CHECK(retention_seconds>=0),byte_quota INTEGER NOT NULL CHECK(byte_quota>=0),record_byte_cap INTEGER NOT NULL CHECK(record_byte_cap>=0),diagnostic_expires_at INTEGER,diagnostic_boot_id TEXT,redaction_profile_version INTEGER NOT NULL CHECK(redaction_profile_version>=1),updated_at INTEGER NOT NULL);
CREATE TABLE client_call_logs(log_id TEXT NOT NULL PRIMARY KEY,client_id TEXT NOT NULL REFERENCES clients ON DELETE CASCADE,call_id TEXT NOT NULL,tool_id TEXT NOT NULL REFERENCES tools,backend_kind TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,decision_code TEXT NOT NULL,outcome_code TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>=1),logging_revision INTEGER NOT NULL CHECK(logging_revision>=1),expires_at INTEGER NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),payload_ciphertext BLOB,key_alias TEXT,CHECK((payload_ciphertext IS NULL)=(key_alias IS NULL)));
CREATE TABLE logging_counters(client_id TEXT NOT NULL PRIMARY KEY REFERENCES clients ON DELETE CASCADE,optional_dropped_count INTEGER NOT NULL CHECK(optional_dropped_count>=0),quota_dropped_count INTEGER NOT NULL CHECK(quota_dropped_count>=0),last_drop_at INTEGER);
CREATE INDEX call_logs_client_time ON client_call_logs(client_id,started_at);
CREATE INDEX call_logs_expiry ON client_call_logs(expires_at);
CREATE INDEX call_logs_client_expiry ON client_call_logs(client_id,expires_at);
CREATE INDEX credentials_client_state ON credentials(client_id,state);
CREATE INDEX rules_by_tool ON client_tool_rules(tool_id);
CREATE INDEX executions_client_time ON executions(client_id,admitted_at);
CREATE INDEX executions_connection_time ON executions(connection_profile_id,admitted_at);
CREATE INDEX targets_connection_enabled ON target_app_profiles(connection_profile_id,enabled);
CREATE INDEX resource_client_enabled ON resource_grants(client_id,enabled);
CREATE INDEX audit_client_time ON audit_events(client_id,occurred_at);
CREATE INDEX audit_time ON audit_events(occurred_at);
CREATE INDEX outbox_delivery ON change_outbox(delivered_at,change_id);
CREATE UNIQUE INDEX execution_idempotency ON executions(client_id,tool_id,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit is append-only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit retention uses a separately authorized maintenance transaction'); END;
COMMIT;
